
// =================================================================== round-3 Hemomancer test (Midjourney-traced sprite)
// Draws the round-3 sheet at 1 sprite px = 1 canvas px (world px = RS*ZK canvas px). No weapon, no skills poses.
{
  const R3 = { fw: 256, fh: 416, ax: 128, ay: 408, fr: {"0/idle/front/0": [0, 0], "0/idle/front/1": [256, 0], "0/idle/front/2": [512, 0], "0/idle/front/3": [768, 0], "0/idle/front/4": [1024, 0], "0/idle/front/5": [1280, 0], "0/walk/front/0": [1536, 0], "0/walk/front/1": [0, 416], "0/walk/front/2": [256, 416], "0/walk/front/3": [512, 416], "0/walk/front/4": [768, 416], "0/walk/front/5": [1024, 416], "0/walk/front/6": [1280, 416], "0/walk/front/7": [1536, 416]} };
  const R3_S = 3;   // canvas px per world px at desktop (RS 4 x ZK 0.75)
  const R3_img = new Image(); let R3_ok = false; R3_img.onload = () => { R3_ok = true; }; R3_img.src = 'data:image/png;base64,';
  // pad so the anchor lands on a whole world pixel
  const padX = (R3_S - R3.ax % R3_S) % R3_S, padY = (R3_S - R3.ay % R3_S) % R3_S;
  const HW = Math.ceil((R3.fw + padX) / R3_S) * R3_S, HH = Math.ceil((R3.fh + padY) / R3_S) * R3_S;
  const WW = HW / R3_S, WH = HH / R3_S, OX = (R3.ax + padX) / R3_S, OY = (R3.ay + padY) / R3_S;
  const CACHE = {};
  const lo = src => { const c = mkCanvas(WW, WH), cx = c.getContext('2d'); cx.imageSmoothingEnabled = false; cx.drawImage(src, 0, 0, WW, WH); c._hr = src; return c; };
  const tint = (src, col) => { const s = src._hr || src, q = mkCanvas(s.width, s.height), qx = q.getContext('2d'); qx.drawImage(s, 0, 0); qx.globalCompositeOperation = 'source-in'; qx.fillStyle = col; qx.fillRect(0, 0, s.width, s.height); return src._hr ? lo(q) : q; };
  function r3Frame(pose, ph) {
    const n = pose === 'walk' ? 8 : 6, key = '0/' + pose + '/front/' + (((ph | 0) % n + n) % n);
    if (CACHE[key]) return CACHE[key];
    const xy = R3.fr[key]; if (!xy) return null;
    const hd = mkCanvas(HW, HH), hx = hd.getContext('2d'); hx.imageSmoothingEnabled = false;
    hx.drawImage(R3_img, xy[0], xy[1], R3.fw, R3.fh, padX, padY, R3.fw, R3.fh);
    const hf = mkCanvas(HW, HH), fx = hf.getContext('2d'); fx.translate(HW, 0); fx.scale(-1, 1); fx.drawImage(hd, 0, 0);
    const c = lo(hd), f = lo(hf);
    const fr = { c, f, fl: tint(c, '#fff'), flf: tint(f, '#fff'), w: WW, h: WH, ox: OX, oy: OY, bb: { x: OX - 22, y: OY - 130, w: 44, h: 131 }, tint, hd: true };
    return CACHE[key] = fr;
  }
  window.__r3Frame = r3Frame;
  const _hf = heroFrame;
  heroFrame = function (cls, pose, ph, view) {
    if (cls !== 'hemomancer' || !R3_ok) return _hf(cls, pose, ph, view);
    return r3Frame(pose === 'walk' ? 'walk' : 'idle', ph) || _hf(cls, pose, ph, view);
  };
  const _hp = heroPose;
  heroPose = function () {
    const r = _hp(); if (P.cls !== 'hemomancer') return r;
    if (r[0] === 'walk') return ['walk', Math.floor((P._wd || 0) * 7.2) % 8];
    return ['idle', Math.floor(G.time * 5) % 6];
  };
}
